/**
 * How many pages each document has, and where its page images live.
 *
 * Generated by tools/book-pages.mjs — run `npm run book-pages` after
 * adding or replacing a PDF. Checked in, because the renderer needs
 * Ghostscript and the CI runner does not have it.
 */
export type Book = { slug: string; pages: number }

export const BOOKS: Record<string, Book> = {
  "/scores/abendlied.pdf": {
    "slug": "scores/abendlied",
    "pages": 8
  },
  "/scores/introduction-and-rondo.pdf": {
    "slug": "scores/introduction-and-rondo",
    "pages": 26
  },
  "/scores/journey-through-latin-america.pdf": {
    "slug": "scores/journey-through-latin-america",
    "pages": 20
  },
  "/papers/introduction-and-rondo.pdf": {
    "slug": "papers/introduction-and-rondo",
    "pages": 13
  },
  "/papers/journey-through-latin-america.pdf": {
    "slug": "papers/journey-through-latin-america",
    "pages": 11
  }
}

/** The image for one page, one-based as a reader counts them. */
export const pageSrc = (slug: string, n: number) =>
  `/pages/${slug}/${String(n).padStart(3, '0')}.jpg`
